    t2_sig = "10001"
    t3_sig = "11100"

    score = 0.0

    t1_data = data[data['A_str'] == t1_sig]
    if len(t1_data) > 0:
        score += np.mean(t1_data['response'] == 1)

    t2_data = data[data['A_str'] == t2_sig]
    if len(t2_data) > 0:
        score += np.mean(t2_data['response'] == 0)

    t3_data = data[data['A_str'] == t3_sig]
    if len(t3_data) > 0:
        score += np.mean(t3_data['response'] == 1)

    return float(score)

